// Validate API key and extract client info from webhook
const headers = $input.first().json.headers || {};
const body = $input.first().json.body || {};

const apiKey = headers['x-api-key'] || headers['authorization']?.replace('Bearer ', '');

if (!apiKey) {
  throw new Error('Missing API key. Include X-API-Key header.');
}

// Extract newsletter_id from request
const newsletterId = body.newsletter_id;
if (!newsletterId) {
  throw new Error('Missing newsletter_id in request body.');
}

return [{
  json: {
    apiKey,
    newsletterId,
    triggerType: 'api',
    requestBody: body
  }
}];

// Return error response for webhook
return [{
  json: {
    success: false,
    error: 'Newsletter not found or unauthorized',
    code: 'UNAUTHORIZED'
  }
}];

// Merge newsletter data from API or Schedule path
const newsletter = $input.first().json;
const triggerType = $('Validate API Key').first()?.json?.triggerType || 'scheduled';

return [{
  json: {
    newsletter: {
      id: newsletter.id,
      clientId: newsletter.client_id,
      name: newsletter.name,
      industry: newsletter.industry,
      maxArticles: newsletter.max_articles || 12,
      aiSummaries: newsletter.ai_summaries_enabled !== false
    },
    branding: {
      title: newsletter.branding_title || newsletter.name,
      subtitle: newsletter.branding_subtitle || `${newsletter.industry} Updates`,
      logoUrl: newsletter.logo_url || '',
      primaryColor: newsletter.primary_color || '#667eea',
      secondaryColor: newsletter.secondary_color || '#764ba2',
      footerText: newsletter.footer_text || `Curated by ${newsletter.company_name}`
    },
    client: {
      id: newsletter.client_id,
      companyName: newsletter.company_name,
      plan: newsletter.plan
    },
    triggerType,
    startTime: Date.now()
  }
}];

// Merge all newsletter configuration
const baseData = $('Prepare Newsletter Data').first().json;
const sources = $('Get Sources').all().map(i => i.json);
const categories = $('Get Categories').all().map(i => i.json);
const channels = $('Get Channels').all().map(i => i.json);
const recipients = $('Get Recipients').all().map(i => i.json);

// Build categories object
const categoriesObj = {};
categories.forEach(cat => {
  categoriesObj[cat.name] = {
    icon: cat.icon || '📰',
    color: cat.color || '#6B7280',
    keywords: cat.keywords || []
  };
});

// Add 'Other' category if not exists
if (!categoriesObj['Other']) {
  categoriesObj['Other'] = { icon: '📰', color: '#6B7280', keywords: [] };
}

// Extract source configs
const rssFeeds = sources.filter(s => s.source_type === 'rss').map(s => s.source_url);
const newsApiKeywords = sources
  .filter(s => s.source_type === 'newsapi')
  .flatMap(s => s.keywords || []);
const excludeKeywords = sources.flatMap(s => s.exclude_keywords || []);

return [{
  json: {
    ...baseData,
    sources: {
      rssFeeds,
      newsApiKeywords: newsApiKeywords.join(', '),
      excludeKeywords: [...new Set(excludeKeywords)]
    },
    categories: categoriesObj,
    channels,
    recipients
  }
}];

// Fetch RSS feeds
const config = $('Merge Configuration').first().json;
const rssFeeds = config.sources.rssFeeds || [];

if (rssFeeds.length === 0) {
  return [{ json: { items: [] } }];
}

// Return feeds for RSS node
return rssFeeds.map(url => ({ json: { feedUrl: url } }));

// Process and merge all news sources
const config = $('Merge Configuration').first().json;
const newsApiResult = $('Fetch NewsAPI').first()?.json || {};
const rssItems = $('Fetch RSS').all().map(i => i.json);

const articles = [];
const excludeKeywords = config.sources.excludeKeywords || [];

// Process NewsAPI
(newsApiResult.articles || []).forEach(article => {
  const text = (article.title + ' ' + (article.description || '')).toLowerCase();
  if (excludeKeywords.some(kw => text.includes(kw.toLowerCase()))) return;

  articles.push({
    title: article.title,
    description: article.description || '',
    url: article.url,
    source: article.source?.name || 'NewsAPI',
    publishedAt: article.publishedAt,
    imageUrl: article.urlToImage || ''
  });
});

// Process RSS
rssItems.forEach(item => {
  if (!item.title) return;
  const text = (item.title + ' ' + (item.contentSnippet || '')).toLowerCase();
  if (excludeKeywords.some(kw => text.includes(kw.toLowerCase()))) return;

  articles.push({
    title: item.title,
    description: item.contentSnippet || item.content || '',
    url: item.link,
    source: item.creator || 'RSS',
    publishedAt: item.pubDate || item.isoDate,
    imageUrl: item.enclosure?.url || ''
  });
});

// Dedupe & sort
const seen = new Set();
const unique = articles.filter(a => {
  const key = a.title.toLowerCase().substring(0, 50);
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

const sorted = unique
  .sort((a, b) => new Date(b.publishedAt) - new Date(a.publishedAt))
  .slice(0, config.newsletter.maxArticles);

return [{ json: { ...config, articles: sorted, articleCount: sorted.length } }];

