// Enrich articles with AI categorization
const data = $('Has Articles?').first().json;
const aiResponse = $input.first().json.message?.content || '{"categorized":[]}';

let categorized = [];
try {
  categorized = JSON.parse(aiResponse.replace(/```json\n?|```/g, '').trim()).categorized || [];
} catch (e) {
  // Fallback to keyword matching
  categorized = data.articles.map((a, i) => {
    const text = (a.title + ' ' + a.description).toLowerCase();
    let cat = 'Other';
    for (const [name, c] of Object.entries(data.categories)) {
      if (c.keywords?.some(kw => text.includes(kw))) { cat = name; break; }
    }
    return { id: i, category: cat, summary: a.description?.substring(0, 100), importance: 5 };
  });
}

// Enrich articles
const enriched = data.articles.map((article, i) => {
  const cat = categorized.find(c => c.id === i) || { category: 'Other', summary: article.description?.substring(0, 100), importance: 5 };
  const catData = data.categories[cat.category] || data.categories['Other'];
  return { ...article, category: cat.category, categoryIcon: catData.icon, categoryColor: catData.color, summary: cat.summary, importance: cat.importance };
});

// Group by category
const grouped = {};
enriched.forEach(a => {
  if (!grouped[a.category]) grouped[a.category] = { icon: a.categoryIcon, color: a.categoryColor, articles: [] };
  grouped[a.category].articles.push(a);
});

// Top story
const topStory = [...enriched].sort((a, b) => b.importance - a.importance)[0];

return [{ json: { ...data, topStory, groupedArticles: grouped, enrichedArticles: enriched } }];

// Generate HTML email with client branding
const d = $input.first().json;
const today = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

let html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1.0">
<style>
*{box-sizing:border-box}body{font-family:'Segoe UI',Tahoma,sans-serif;background:#f0f4f8;margin:0;padding:20px;line-height:1.6}
.container{max-width:680px;margin:0 auto;background:#fff;border-radius:16px;overflow:hidden;box-shadow:0 4px 20px rgba(0,0,0,.1)}
.header{background:linear-gradient(135deg,${d.branding.primaryColor} 0%,${d.branding.secondaryColor} 100%);color:#fff;padding:40px 30px;text-align:center}
.header h1{margin:0;font-size:28px}.header .sub{margin:10px 0 0;opacity:.9;font-size:15px}.header .stats{margin-top:20px;background:rgba(255,255,255,.2);padding:8px 20px;border-radius:20px;display:inline-block;font-size:14px}
.toc{background:#f8fafc;padding:25px 30px;border-bottom:1px solid #e2e8f0}.toc h3{margin:0 0 15px;font-size:13px;text-transform:uppercase;letter-spacing:1px;color:#64748b}
.toc-list{display:flex;flex-wrap:wrap;gap:10px}.toc-item{display:inline-flex;align-items:center;gap:6px;padding:8px 14px;background:#fff;border-radius:8px;font-size:13px;color:#475569;border:1px solid #e2e8f0}
.toc-count{background:#e2e8f0;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600}
.top-story{padding:30px;background:linear-gradient(135deg,#fef3c7,#fde68a)}.top-story-badge{background:#f59e0b;color:#fff;padding:6px 12px;border-radius:6px;font-size:12px;font-weight:600;text-transform:uppercase;display:inline-block;margin-bottom:15px}
.top-story h2{margin:0 0 12px;font-size:22px;line-height:1.3}.top-story h2 a{color:#1e293b;text-decoration:none}.top-story .summary{color:#57534e;font-size:15px;margin:0 0 15px}.top-story .meta{font-size:13px;color:#78716c}
.content{padding:30px}.cat-section{margin-bottom:30px}.cat-header{display:flex;align-items:center;gap:10px;margin-bottom:20px;padding-bottom:12px;border-bottom:2px solid}.cat-icon{font-size:22px}.cat-title{margin:0;font-size:18px;font-weight:600;color:#1e293b}.cat-count{font-size:13px;color:#64748b;margin-left:auto}
.article{background:#f8fafc;border-radius:12px;padding:18px;margin-bottom:12px;border-left:4px solid}.article h3{margin:0 0 8px;font-size:15px;font-weight:600;line-height:1.4}.article h3 a{color:#1e293b;text-decoration:none}.article .summary{color:#64748b;margin:0 0 10px;font-size:13px}.article .meta{font-size:12px;color:#94a3b8;display:flex;gap:12px}.article .read{color:${d.branding.primaryColor};text-decoration:none;font-weight:500;margin-left:auto}
.footer{background:linear-gradient(135deg,#1e293b,#334155);color:#fff;padding:30px;text-align:center}.footer p{margin:0 0 8px;font-size:14px;opacity:.9}.footer .brand{font-size:16px;font-weight:600;margin-bottom:12px}
</style></head><body><div class="container">
<div class="header"><h1>${d.branding.title}</h1><p class="sub">${d.branding.subtitle}</p><p class="sub" style="font-size:13px;opacity:.7">${today}</p><div class="stats">📰 ${d.enrichedArticles.length} articles • ${Object.keys(d.groupedArticles).length} categories</div></div>
<div class="toc"><h3>📋 In This Issue</h3><div class="toc-list">`;

for (const [cat, data] of Object.entries(d.groupedArticles)) {
  html += `<span class="toc-item"><span>${data.icon}</span><span>${cat}</span><span class="toc-count">${data.articles.length}</span></span>`;
}

html += `</div></div>
<div class="top-story"><div class="top-story-badge">⭐ Top Story</div><h2><a href="${d.topStory.url}">${d.topStory.title}</a></h2><p class="summary">${d.topStory.summary}</p><div class="meta">${d.topStory.categoryIcon} ${d.topStory.category} • ${d.topStory.source}</div></div>
<div class="content">`;

for (const [cat, data] of Object.entries(d.groupedArticles)) {
  html += `<div class="cat-section"><div class="cat-header" style="border-color:${data.color}"><span class="cat-icon">${data.icon}</span><h2 class="cat-title">${cat}</h2><span class="cat-count">${data.articles.length}</span></div>`;
  data.articles.forEach(a => {
    const date = new Date(a.publishedAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
    html += `<div class="article" style="border-color:${data.color}"><h3><a href="${a.url}">${a.title}</a></h3><p class="summary">${a.summary}</p><div class="meta"><span>${a.source}</span><span>${date}</span><a href="${a.url}" class="read">Read →</a></div></div>`;
  });
  html += `</div>`;
}

html += `</div><div class="footer"><p class="brand">${d.branding.footerText}</p><p>Your daily ${d.newsletter.industry} intelligence</p></div></div></body></html>`;

return [{ json: { ...d, htmlContent: html, subject: `${d.branding.title} - ${today}` } }];

// Generate Telegram message
const d = $input.first().json;
const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' });
const esc = t => t.replace(/[_*\[\]()~`>#+=|{}.!-]/g, '\\$&');

let msg = `*${esc(d.branding.title)}*\n_${esc(d.branding.subtitle)} • ${esc(today)}_\n━━━━━━━━━━━━━━━━━━━━\n\n`;
msg += `⭐ *TOP STORY*\n${d.topStory.categoryIcon} [${esc(d.topStory.title.substring(0,60))}](${d.topStory.url})\n_${esc(d.topStory.summary)}_\n\n━━━━━━━━━━━━━━━━━━━━\n\n`;

let count = 0;
for (const [cat, data] of Object.entries(d.groupedArticles)) {
  if (count >= 6) break;
  msg += `${data.icon} *${esc(cat)}*\n`;
  data.articles.slice(0, 2).forEach(a => {
    if (count >= 6) return;
    msg += `  • [${esc(a.title.substring(0,50))}...](${a.url})\n`;
    count++;
  });
  msg += '\n';
}

if (d.enrichedArticles.length > 6) msg += `📧 _\\+${d.enrichedArticles.length - 6} more in email_\n`;
msg += `\n━━━━━━━━━━━━━━━━━━━━\n_${esc(d.client.companyName)}_`;

return [{ json: { ...d, telegramMessage: msg } }];

// Send to all enabled channels
const d = $input.first().json;
const results = { email: null, telegram: null, slack: null };

// Return data for channel nodes
return [{ json: { ...d, channelResults: results } }];

// Return success response
const data = $('Prepare Newsletter Data').first().json;
const articleCount = $('Process Articles').first().json.articleCount;
const recipientCount = $('Get Recipients').all().length;

return [{
  json: {
    success: true,
    newsletter_id: data.newsletter.id,
    newsletter_name: data.newsletter.name,
    articles_sent: articleCount,
    recipients: recipientCount,
    channels: ['email', 'telegram'],
    delivered_at: new Date().toISOString()
  }
}];

// No articles found response
return [{
  json: {
    success: true,
    message: 'No articles found for today',
    articles_sent: 0
  }
}];
